from __future__ import annotations

import logging
import os
from collections import defaultdict, deque
from dataclasses import dataclass
from typing import Callable, Deque, Dict, Iterable, List, Mapping, Protocol, Tuple

import boto3
from botocore.config import Config
from botocore.exceptions import ClientError, EndpointConnectionError

logger = logging.getLogger(__name__)

DEPLOYMENT_PROFILE_ENV = "DEPLOYMENT_PROFILE"
DEFAULT_PROFILE = "onprem"
AWS_PROFILE = "aws"
ONPREM_PROFILE = "onprem"


class AdapterSetupError(Exception):
    """Raised when the adapter registry cannot satisfy a runtime profile contract."""


class ObjectStoragePort(Protocol):
    """Port for storing and retrieving binary objects."""

    def store(self, bucket: str, key: str, data: bytes) -> None:
        """Persist binary data to the provided bucket/key."""
        ...

    def retrieve(self, bucket: str, key: str) -> bytes:
        """Retrieve binary data previously written to the provided bucket/key."""
        ...


class QueuePort(Protocol):
    """Port that exposes queueing primitives in a profile-agnostic way."""

    def enqueue(self, queue_name: str, payload: bytes) -> None:
        """Push a payload to the named queue."""
        ...

    def dequeue(self, queue_name: str) -> bytes | None:
        """Retrieve the next payload from the queue, or None if empty."""
        ...

    def pending(self, queue_name: str) -> Tuple[bytes, ...]:
        """Return a snapshot of pending payloads."""
        ...


class EventingPort(Protocol):
    """Port that exposes lightweight event publication."""

    def publish_event(self, event_type: str, payload: Mapping[str, str]) -> None:
        """Publish an event with a structured payload."""
        ...

    def recent_events(self, event_type: str | None = None) -> Tuple[Mapping[str, str], ...]:
        """Return recorded events, optionally filtered by event_type."""
        ...


class SecretsPort(Protocol):
    """Port that exposes secrets storage semantics."""

    def store_secret(self, identifier: str, value: str) -> None:
        """Persist a secret value for the identifier."""
        ...

    def retrieve_secret(self, identifier: str) -> str:
        """Retrieve a previously stored secret."""
        ...

    def list_secret_ids(self) -> Tuple[str, ...]:
        """List identifiers that currently host secrets."""
        ...


class LogSinkPort(Protocol):
    """Port that mirrors log sink behavior."""

    def emit(self, message: str, level: str = "INFO", context: Mapping[str, str] | None = None) -> None:
        """Emit a log entry."""
        ...

    def records(self) -> Tuple[Mapping[str, str], ...]:
        """Return the list of emitted log entries for inspection."""
        ...


@dataclass
class AdapterSet:
    """Profile-specific adapters bundled together for downstream importers."""

    profile_name: str
    object_storage: ObjectStoragePort
    queue: QueuePort
    eventing: EventingPort
    secrets: SecretsPort
    log_sink: LogSinkPort


@dataclass(frozen=True)
class ObjectStorageConfig:
    endpoint_url: str
    access_key: str
    secret_key: str
    region: str
    verify_tls: bool


def _str_to_bool(value: str | None, default: bool) -> bool:
    if value is None:
        return default
    lowered = value.strip().lower()
    if lowered in {"1", "true", "yes", "on"}:
        return True
    if lowered in {"0", "false", "no", "off"}:
        return False
    return default


class Boto3S3Adapter(ObjectStoragePort):
    """S3-compatible adapter used by all profiles that target S3 endpoints."""

    def __init__(
        self,
        endpoint_url: str,
        access_key: str,
        secret_key: str,
        region: str,
        verify_tls: bool,
    ) -> None:
        if not endpoint_url:
            raise ValueError("endpoint_url is required for object storage adapters")
        self._endpoint_url = endpoint_url
        self._region = region or "us-east-1"

        client_config = Config(signature_version="s3v4")
        self._client = boto3.client(
            "s3",
            endpoint_url=endpoint_url,
            aws_access_key_id=access_key,
            aws_secret_access_key=secret_key,
            region_name=self._region,
            config=client_config,
            verify=verify_tls,
        )

    @classmethod
    def from_config(cls, config: ObjectStorageConfig) -> "Boto3S3Adapter":
        return cls(
            endpoint_url=config.endpoint_url,
            access_key=config.access_key,
            secret_key=config.secret_key,
            region=config.region,
            verify_tls=config.verify_tls,
        )

    def store(self, bucket: str, key: str, data: bytes) -> None:
        self._ensure_bucket(bucket)
        self._client.put_object(Bucket=bucket, Key=key, Body=data)

    def retrieve(self, bucket: str, key: str) -> bytes:
        try:
            response = self._client.get_object(Bucket=bucket, Key=key)
        except ClientError as err:
            code = err.response.get("Error", {}).get("Code", "")
            if code in {"NoSuchKey", "404", "NotFound"}:
                raise KeyError(f"{bucket}/{key}") from err
            raise
        return response["Body"].read()

    def _ensure_bucket(self, bucket: str) -> None:
        try:
            self._client.head_bucket(Bucket=bucket)
        except ClientError as err:
            code = err.response.get("Error", {}).get("Code", "")
            if code in {"404", "NoSuchBucket", "NotFound"}:
                self._create_bucket(bucket)
                return
            raise
        except EndpointConnectionError:
            raise

    def _create_bucket(self, bucket: str) -> None:
        if self._region == "us-east-1":
            self._client.create_bucket(Bucket=bucket)
            return
        self._client.create_bucket(
            Bucket=bucket,
            CreateBucketConfiguration={"LocationConstraint": self._region},
        )


class InMemoryQueueAdapter(QueuePort):
    """Lightweight queue implementation that satisfies both profiles."""

    def __init__(self, profile: str) -> None:
        self._profile = profile
        self._queues: Dict[str, Deque[bytes]] = defaultdict(deque)

    def enqueue(self, queue_name: str, payload: bytes) -> None:
        self._queues[queue_name].append(payload)

    def dequeue(self, queue_name: str) -> bytes | None:
        queue = self._queues[queue_name]
        if not queue:
            return None
        return queue.popleft()

    def pending(self, queue_name: str) -> Tuple[bytes, ...]:
        return tuple(self._queues[queue_name])


class InMemoryEventingAdapter(EventingPort):
    """Emit events to an in-memory ledger that is distinct per profile."""

    def __init__(self, profile: str) -> None:
        self._profile = profile
        self._events: Dict[str, List[Mapping[str, str]]] = defaultdict(list)

    def publish_event(self, event_type: str, payload: Mapping[str, str]) -> None:
        self._events[event_type].append({"payload": str(payload), "profile": self._profile})

    def recent_events(self, event_type: str | None = None) -> Tuple[Mapping[str, str], ...]:
        if event_type:
            return tuple(self._events[event_type])
        payloads: List[Mapping[str, str]] = []
        for entries in self._events.values():
            payloads.extend(entries)
        return tuple(payloads)


class InMemorySecretsAdapter(SecretsPort):
    """Secrets adapter for ephemeral workloads."""

    def __init__(self, profile: str) -> None:
        self._profile = profile
        self._storage: Dict[str, str] = {}

    def store_secret(self, identifier: str, value: str) -> None:
        self._storage[identifier] = f"{value} (profile={self._profile})"

    def retrieve_secret(self, identifier: str) -> str:
        try:
            return self._storage[identifier]
        except KeyError as err:
            raise KeyError(f"secret {identifier} not found") from err

    def list_secret_ids(self) -> Tuple[str, ...]:
        return tuple(self._storage.keys())


class BufferedLogSinkAdapter(LogSinkPort):
    """In-memory log sink that can be inspected in tests and tooling."""

    def __init__(self, profile: str) -> None:
        self._profile = profile
        self._records: List[Mapping[str, str]] = []

    def emit(self, message: str, level: str = "INFO", context: Mapping[str, str] | None = None) -> None:
        envelope = {"profile": self._profile, "level": level, "message": message}
        if context:
            envelope.update(context)
        self._records.append(envelope)
        logger.debug("Log emitted: %s", envelope)

    def records(self) -> Tuple[Mapping[str, str], ...]:
        return tuple(self._records)


def _aws_object_storage_config() -> ObjectStorageConfig:
    return ObjectStorageConfig(
        endpoint_url=os.getenv("AWS_S3_ENDPOINT", "http://localhost:4566"),
        access_key=os.getenv("AWS_ACCESS_KEY_ID", "test"),
        secret_key=os.getenv("AWS_SECRET_ACCESS_KEY", "test"),
        region=os.getenv("AWS_REGION", "us-east-1"),
        verify_tls=_str_to_bool(os.getenv("AWS_S3_VERIFY_TLS"), False),
    )


def _onprem_object_storage_config() -> ObjectStorageConfig:
    return ObjectStorageConfig(
        endpoint_url=os.getenv("MINIO_ENDPOINT", "http://localhost:9000"),
        access_key=os.getenv("MINIO_ACCESS_KEY", "minioadmin"),
        secret_key=os.getenv("MINIO_SECRET_KEY", "minioadmin"),
        region=os.getenv("MINIO_REGION", "us-east-1"),
        verify_tls=_str_to_bool(os.getenv("MINIO_VERIFY_TLS"), False),
    )


def _build_aws_adapter_set() -> AdapterSet:
    return AdapterSet(
        profile_name=AWS_PROFILE,
        object_storage=Boto3S3Adapter.from_config(_aws_object_storage_config()),
        queue=InMemoryQueueAdapter(AWS_PROFILE),
        eventing=InMemoryEventingAdapter(AWS_PROFILE),
        secrets=InMemorySecretsAdapter(AWS_PROFILE),
        log_sink=BufferedLogSinkAdapter(AWS_PROFILE),
    )


def _build_onprem_adapter_set() -> AdapterSet:
    return AdapterSet(
        profile_name=ONPREM_PROFILE,
        object_storage=Boto3S3Adapter.from_config(_onprem_object_storage_config()),
        queue=InMemoryQueueAdapter(ONPREM_PROFILE),
        eventing=InMemoryEventingAdapter(ONPREM_PROFILE),
        secrets=InMemorySecretsAdapter(ONPREM_PROFILE),
        log_sink=BufferedLogSinkAdapter(ONPREM_PROFILE),
    )


class AdapterRegistry:
    """Registry that hands out adapters according to DEPLOYMENT_PROFILE."""

    SUPPORTED_PROFILES: Tuple[str, ...] = (AWS_PROFILE, ONPREM_PROFILE)
    _builders: Dict[str, Callable[[], AdapterSet]] = {
        AWS_PROFILE: _build_aws_adapter_set,
        ONPREM_PROFILE: _build_onprem_adapter_set,
    }

    @classmethod
    def _normalize_profile(cls, profile: str | None) -> str:
        raw = (profile or os.getenv(DEPLOYMENT_PROFILE_ENV, DEFAULT_PROFILE)).strip().lower()
        if raw not in cls.SUPPORTED_PROFILES:
            raise AdapterSetupError(
                f"profile '{raw}' is not supported; expecting one of {cls.SUPPORTED_PROFILES}"
            )
        return raw

    @classmethod
    def get_adapter_set(cls, profile: str | None = None) -> AdapterSet:
        normalized = cls._normalize_profile(profile)
        builder = cls._builders[normalized]
        return builder()


def get_adapter_set(profile: str | None = None) -> AdapterSet:
    """Convenience function for downstream importers."""
    return AdapterRegistry.get_adapter_set(profile)
