import os
from uuid import uuid4

import pytest
from botocore.exceptions import ClientError, EndpointConnectionError

from shared.adapters import AdapterSetupError, get_adapter_set

REQUIRED_PROFILES = ("aws", "onprem")


def _build_bucket_name(profile: str) -> str:
    override = os.getenv(f"REQ001_{profile.upper()}_BUCKET_PREFIX")
    if override:
        return override
    return f"kit-req-001-{profile}-{uuid4().hex[:8]}"


def _profile_session(profile: str):
    return {"DEPLOYMENT_PROFILE": profile}


@pytest.mark.parametrize("profile", REQUIRED_PROFILES)
def test_object_storage_round_trip(profile: str):
    os.environ["DEPLOYMENT_PROFILE"] = profile
    bucket = _build_bucket_name(profile)
    key = f"payload-{uuid4().hex}"
    payload = f"payload-{profile}-{uuid4().hex}".encode()
    try:
        adapters = get_adapter_set(profile)
    except AdapterSetupError as exc:
        pytest.skip(f"Profile {profile} cannot be resolved: {exc}")

    object_storage = adapters.object_storage
    try:
        object_storage.store(bucket, key, payload)
        retrieved = object_storage.retrieve(bucket, key)
    except EndpointConnectionError as exc:
        pytest.skip(f"{profile} object storage endpoint is unreachable: {exc}")
    except ClientError as exc:
        pytest.skip(f"{profile} object storage request failed (service may be down): {exc}")

    assert retrieved == payload
